const { siraylaIsle, tekrarDene, say, ortalama, grupla } = require('./islem.js');

(async () => {
  // siraylaIsle sıralı çalışmalı (zamanlama ile doğrula)
  const siralar = [];
  const r = await siraylaIsle([1, 2, 3], async (x) => {
    siralar.push('basla-' + x);
    await new Promise(r => setTimeout(r, 50));
    siralar.push('bit-' + x);
    return x;
  });
  console.log('siraylaIsle siralama:', JSON.stringify(siralar));
  // basla-1, bit-1, basla-2, bit-2, basla-3, bit-3 olmalı (paralel değil)

  // tekrarDene: 2 denemede başarılı
  let denemeNumarasi = 0;
  const r2 = await tekrarDene(async (i) => {
    denemeNumarasi++;
    if (i < 1) throw new Error('ilk deneme');
    return 'basarili';
  }, 3);
  console.log('tekrarDene sonucu:', r2, 'denemeSayisi:', denemeNumarasi); // basarili, 2

  // tekrarDene: hep başarısız → hata fırlatmalı
  try {
    await tekrarDene(() => { throw new Error('olmaz'); }, 2);
    console.log('tekrarDene HATA: hata fırlatmadı!');
  } catch(e) {
    console.log('tekrarDene olumlu: hata fırlatıldı:', e.message);
  }

  // say
  console.log('say:', JSON.stringify(say(['a','b','a','a','b']))); // {a:3,b:2}

  // ortalama
  console.log('ortalama [2,4]:', ortalama([2,4])); // 3
  console.log('ortalama []:', ortalama([])); // 0

  // grupla
  console.log('grupla:', JSON.stringify(grupla([1,2,1,2,3], x => x % 2)));
})();
"

